'use client';

import { useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';

gsap.registerPlugin(ScrollTrigger);

/**
 * Barra de progreso de scroll fija arriba de la página.
 * El ancho se actualiza en el onUpdate del ScrollTrigger vía gsap.set,
 * no con estado de React, para no re-renderizar en cada frame de scroll.
 */
export default function ScrollProgressBar() {
  const barRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    const trigger = ScrollTrigger.create({
      trigger: document.documentElement,
      start: 'top top',
      end: 'bottom bottom',
      onUpdate: (self) => {
        gsap.set(barRef.current, { scaleX: self.progress });
      },
    });

    return () => trigger.kill();
  }, []);

  return (
    <div
      className="fixed top-0 left-0 z-50 h-1 w-full"
      role="progressbar"
      aria-label="Progreso de scroll"
      aria-valuemin={0}
      aria-valuemax={100}
    >
      <div
        ref={barRef}
        className="h-full w-full origin-left scale-x-0 bg-[--color-accent]"
      />
    </div>
  );
}
```

Notas:
- Usa `useGSAP` (`@gsap/react`, ya está en tu `package.json`) en vez de `useEffect` manual: crea el contexto y limpia el `ScrollTrigger` al desmontar sin código extra.
- `gsap.set(..., { scaleX })` en el `onUpdate` en vez de `setState`, para no forzar un render de React en cada scroll.
- Montalo una sola vez en el layout raíz (fuera del `<main>`, para que no se scrollee con el contenido).
- El color usa el token `--color-accent` — cambialo por el que tengas definido en tu `@theme` de Tailwind v4 (o reemplazá por una clase `bg-*` fija si preferís).
- Si en esta web tenés Lenis activo (está en tus deps) para scroll suave, este `ScrollTrigger` necesita estar sincronizado con Lenis (`lenis.on('scroll', ScrollTrigger.update)` + `gsap.ticker`) donde sea que inicialices Lenis, si no el progreso no va a coincidir con el scroll real. Avisame si querés que te arme ese wiring también.

